#pragma once
// Per-function call counters for a window of recompiled functions (reverse
// engineering aid). The table is generated by tools/gen-call-counter.ps1.
#include <ppc_context.h>

#include <atomic>
#include <cstdint>

extern const uint32_t g_callCounterAddresses[];
extern const uint32_t g_callCounterCount;
extern std::atomic<uint32_t> g_callCounters[];

namespace CallCounter
{
    // Prints functions called during the last `frames` frames, sorted by calls per frame,
    // then resets the counters.
    void Report(uint64_t frames);
    // PES_CALL_WATCH=<hex,hex,...>: logs first calls and totals of the listed functions.
    void StartWatch();
}
